package com.phoenix.business.config;import com.phoenix.business.domain.User;import com.phoenix.business.repository.UserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class BootstrapOwner implements ApplicationRunner {private final UserRepository users;private final PasswordEncoder encoder;private final String username,password;public BootstrapOwner(UserRepository u,PasswordEncoder e,@Value("${app.bootstrap-owner-username}")String n,@Value("${app.bootstrap-owner-password:}")String p){users=u;encoder=e;username=n;password=p;}@Override @Transactional public void run(ApplicationArguments args){if(users.count()>0)return;if(password==null||!password.matches("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}$"))throw new IllegalStateException("BOOTSTRAP_OWNER_PASSWORD is required on an empty database and must meet password policy");User u=new User();u.setUsername(username);u.setDisplayName("Gym Owner");u.setRole(User.Role.OWNER);u.setActive(true);u.setForcePasswordChange(true);u.setPasswordHash(encoder.encode(password));users.save(u);}}
